TLM.f("Sancti/03-27",{"officium":"S. Joannis Damasceni Confessoris","rule":["Evangelium non appropriatum","vide C5;","Gloria","CredoDA"],"fallback":"Commune/C5","sections":{"Introitus":[{"k":"ref","la":"Ps 72:24"},{"k":"text","la":"Tenuísti manum déxteram meam: et in voluntáte tua deduxísti me, et cum glória suscepísti me."},{"k":"ref","la":"Ps 72:1"},{"k":"text","la":"Quam bonus Israël Deus his, qui recto sunt corde!"},{"k":"macro","name":"Gloria"},{"k":"text","la":"Tenuísti manum déxteram meam: et in voluntáte tua deduxísti me, et cum glória suscepísti me."}],"Oratio":[{"k":"text","la":"Omnípotens sempitérne Deus, qui, ad cultum sacrárum imáginum asseréndum, beátum Joánnem cœlésti doctrína et admirábili spíritus fortitúdine imbuísti: concéde nobis ejus intercessióne et exémplo; ut, quorum cólimus imagines, virtútes imitémur et patrocínia sentiámus."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio libri Sapiéntiæ"},{"k":"ref","la":"Sap 10:10-14"},{"k":"text","la":"Justum dedúxit Dóminus per vias rectas, et ostendit illi regnum Dei, et dedit illi sciéntiam sanctórum: honestávit illum in labóribus, et complévit labores illíus. In fraude circumveniéntium illum áffuit illi, et honéstum fecit illum. Custodívit illum ab inimícis, et a seductóribus tutávit illum, et certámen forte dedit illi, ut vínceret et sciret, quóniam ómnium poténtior est sapiéntia. Hæc vénditum justum non derelíquit, sed a peccatóribus liberávit eum: descendítque cum illo in fóveam, et in vínculis non derelíquit illum, donec afférret illi sceptrum regni, et poténtiam advérsus eos, qui eum deprimébant: et mendáces osténdit, qui maculavérunt illum, et dedit illi claritátem ætérnam, Dóminus, Deus noster."}],"Graduale":[{"k":"text","la":"Deus, qui præcínxit me virtúte: et pósuit immaculátam viam meam."},{"k":"text","la":"Qui docet manus meas ad prœ́lium: et posuísti, ut arcum æreum, bráchia mea.","mark":"V"},{"k":"text","la":"Allelúja, allelúja."},{"k":"text","la":"Dedísti mihi protectiónem salútis tuæ: et déxtera tua suscépit me. Allelúja.","mark":"V"}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja"},{"k":"ref","la":"Ps 25:26 et 28"},{"k":"text","la":"Dóminus salvávit manum tuam tibi: quia prœ́lia Dómini tu prœliáris. Allelúja."},{"k":"ref","la":"Ps 143:1"},{"k":"text","la":"Benedíctus Dóminus, Deus meus, qui docet manus meas ad prœ́lium, et dígitos meos ad bellum. Allelúja."}],"Tractus":[{"k":"ref","la":"Ps 17:33 et 35"},{"k":"text","la":"Deus, qui præcínxit me virtúte: et pósuit immaculátam viam meam."},{"k":"text","la":"Qui docet manus meas ad prœ́lium: et posuísti, ut arcum æreum, bráchia mea.","mark":"V"},{"k":"sep"},{"k":"rubric","la":"Tractus"},{"k":"ref","la":"Ps 38:39 et 50"},{"k":"text","la":"Pérsequar inimícos meos, et comprehéndam illos."},{"k":"text","la":"Confríngam illos, nec poterunt stare: cadent subtus pedes meos.","mark":"V"},{"k":"text","la":"Proptérea confitébor in natiónibus, Dómine, et nómini tuo psalmum dicam.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Lucam"},{"k":"ref","la":"Luc 6:6-11"},{"k":"text","la":"In illo témpore: Factum est et in álio sábbato, ut intráret Jesus in synagógam et docéret. Et erat ibi homo, et manus ejus déxtera erat árida. Observábant autem scribæ et pharisæi, si in sábbato curáret: ut invenírent, unde accusárent eum. Ipse vero sciébat cogitatiónes eórum. Et ait hómini, qui habébat manum áridam: Surge et sta in médium. Et surgens stetit. Ait autem ad illos Jesus: Intérrogo vos, si licet sábbatis benefácere, an male: ánimam salvam fácere, an pérdere? Et circumspéctis ómnibus dixit hómini: Exténde manum tuam. Et exténdit: et restitúta est manus ejus. Ipsi autem repléti sunt insipiéntia, et colloquebántur ad ínvicem, quidnam fácerent Jesu."}],"Offertorium":[{"k":"ref","la":"Job 14:7"},{"k":"text","la":"Lignum habet spem: si præcísum fúerit, rursum viréscit, et rami ejus púllulant."}],"Secreta":[{"k":"text","la":"Ut, quæ tibi, Dómine, offérimus, dona tuo sint digna conspéctu: beáti Joánnis et Sanctórum, quos ejus ópera expósitos in templis cólimus, pia suffragátio conspíret."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Ps 36:17"},{"k":"text","la":"Bráchia peccatórum conteréntur, confírmat autem justos Dóminus."}],"Postcommunio":[{"k":"text","la":"Sumpta nos, quǽsumus, Dómine, dona cœléstibus armis tueántur: et beáti Joánnis patrocínia circúmdent Sanctórum unánimi suffrágio cumuláta; quorum imágines evícit in Ecclésia esse venerándas."},{"k":"macro","name":"Per Dominum"}]},"hr":{"788cc75c49120b17":{"t":"<i>Pomolimo se</i>.\nSvemogući vječni Bože, koji si u obranu štovanja svetih slika unio u blaženog Ivana nebeski nauk i čudesnu snagu duha, podaj da po njegovom zagovoru i primjeru nasljedujemo kreposti i osjetimo zaštitu onih čije slike štujemo.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.\n[preveo M.B.; po uredbi iz 1967. nisu u korizmi dozvoljeni spomeni, pa su molitve za ovaj dan ispuštene iz Radićevog prijevoda Misala.]","kn":"Svemogući, vječni Bože, koji si blaženog Ivana obdario nebeskom naukom i divotnom jakošću duha da brani čašćenje svetih slika, dopusti, njegovim zagovorom 1 primjerom, da nasljedujemo kreposti i osjetimo zagovor onih, kojih slike štujemo, po G. n.","knRef":"Kniewald 1942, str. 536–537 (snimka 269) (OCR)"},"b3bb511b6e2587c0":{"t":"Da darovi koje ti, Gospodine, prinosimo budu dostojni tvome pogledu, neka pomogne sveti zagovor blaženog Ivana i svetaca koje njegovom zaslugom izložene štujemo u hramovima.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.\n[preveo M.B.; po uredbi iz 1967. nisu u korizmi dozvoljeni spomeni, pa su molitve za ovaj dan ispuštene iz Radićevog prijevoda Misala.]"},"a62c1f63aa56ebd6":{"t":"<i>Pomolimo se</i>.\nNeka nas, molimo, Gospodine, primljeni darovi štite nebeskim oružjem i neka zagovor blaženog Ivana okruži sjedinjeni glas svetaca, čijim je slikama u Crkvi izborio štovanje.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.\n[preveo M.B.; po uredbi iz 1967. nisu u korizmi dozvoljeni spomeni, pa su molitve za ovaj dan ispuštene iz Radićevog prijevoda Misala.]","kn":"Branili nas. Gospodine, darovi, što ih primismio, nebeskom snagom i okružio nas zagovor blaženoga Ivana, sjedinjen sa zagovorom svih svetih, jer je njegovom zaslugom ostalo u Crkvi poštivanje njihovih slika, po G. n.","knRef":"Kniewald 1942, str. 536–537 (snimka 269) (OCR)"}}});
